{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--glass:#ffffff22;--glass-2:#ffffff16;--accent:#4a8f7e;--muted:#7b8a90;--bg:#f4f7f6;--card:#ffffffee}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#123; background:linear-gradient(180deg,var(--bg),#eef3f2);}
    .app{min-height:100vh;display:flex;flex-direction:column;background-image:url('assets/img/pattern.svg');background-repeat:repeat;}
    header{backdrop-filter:blur(8px);background:linear-gradient(90deg,var(--glass),transparent);border-bottom:1px solid rgba(255,255,255,0.12);display:flex;align-items:center;justify-content:space-between;padding:18px 28px}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#6fb7a3);display:grid;place-items:center;color:white;font-weight:700}
    nav a{margin:0 10px;color:rgba(0,10,12,0.7);text-decoration:none;font-weight:600}
    .hero{padding:48px 28px;display:flex;gap:24px;align-items:center}
    .hero-left{flex:1}
    h1{margin:0 0 8px 0;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .controls{display:flex;gap:14px;align-items:center;margin-top:18px}
    .toggle{background:var(--glass-2);border-radius:999px;padding:6px;border:1px solid rgba(255,255,255,0.06);display:inline-flex}
    .toggle button{border:0;background:transparent;padding:8px 12px;border-radius:999px;cursor:pointer;color:var(--muted);font-weight:600}
    .toggle button.active{background:linear-gradient(180deg,rgba(255,255,255,0.06),rgba(255,255,255,0.02));color:var(--accent);box-shadow:0 6px 18px rgba(20,30,30,0.06)}
    .plans{display:flex;gap:18px;padding:20px 28px 48px}
    .card{background:var(--card);border-radius:14px;padding:18px;flex:1;box-shadow:0 8px 30px rgba(16,22,24,0.06);border:1px solid rgba(255,255,255,0.5)}
    .card h3{margin:0 0 10px 0}
    .price{font-size:26px;color:var(--accent);font-weight:800}
    .meta{color:var(--muted);margin-top:6px}
    .features{margin:12px 0 18px 0;color:#334}
    .cta{display:inline-block;padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#6fb7a3);color:#fff;text-decoration:none;font-weight:700}
    footer{margin-top:auto;padding:18px 28px;color:var(--muted);font-size:13px}
    /* small */
    @media(max-width:880px){.plans{flex-direction:column}.hero{padding:28px}.hero-left h1{font-size:22px}}
  </style>
</head>
<body>
  <div class="app">
    <header>
      <div class="brand">
        <div class="logo">HM</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="services.html">Offerings</a>
        <a href="conditions.html">Ailments</a>
        <a href="approach.html">Method</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">Who We Are</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Reach Out</a>
      </nav>
    </header>

    <main>
      <section class="hero">
        <div class="hero-left">
          <h1>Membership and short programs designed for real life shifts</h1>
          <p class="lead">Flexible participation, clear milestones, and guided adjustments across body, mind, and lifestyle. Choose what fits your season.</p>

          <div class="controls">
            <div class="toggle" role="tablist" aria-label="Pricing view">
              <button id="btn-monthly" class="active" aria-pressed="true">Monthly</button>
              <button id="btn-package" aria-pressed="false">3-Month Package</button>
            </div>
            <div style="color:var(--muted);font-size:14px">Toggle to compare recurring vs. bundled engagement.</div>
          </div>
        </div>

        <div style="max-width:360px">
          <div style="background:var(--glass);padding:14px;border-radius:12px;border:1px solid rgba(255,255,255,0.06);">
            <strong>Need help deciding?</strong>
            <p style="margin:8px 0 0;color:var(--muted)">Try the "Mood-to-Method" in our About page to tailor a recommendation to how you feel today.</p>
          </div>
        </div>
      </section>

      <section class="plans" aria-live="polite">
        <article class="card" data-monthly="89" data-package="240">
          <h3>Starter Circle</h3>
          <div class="price"><span class="num">89</span><span style="font-size:13px;color:var(--muted)"> /mo</span></div>
          <div class="meta">Monthly access + biweekly group check-ins</div>
          <div class="features">Weekly practices, resource library, monthly Q&amp;A</div>
          <a class="cta" href="{{PRIMARY_CTA_URL}}">Join Starter</a>
        </article>

        <article class="card" data-monthly="169" data-package="460">
          <h3>Root Support</h3>
          <div class="price"><span class="num">169</span><span style="font-size:13px;color:var(--muted)"> /mo</span></div>
          <div class="meta">One-on-one check-ins + personalized plan</div>
          <div class="features">Initial consultation, monthly progress session, targeted adjustments</div>
          <a class="cta" href="{{PRIMARY_CTA_URL}}">Enroll in Root Support</a>
        </article>

        <article class="card" data-monthly="329" data-package="880">
          <h3>Foundations Intensive</h3>
          <div class="price"><span class="num">329</span><span style="font-size:13px;color:var(--muted)"> /mo</span></div>
          <div class="meta">Comprehensive plan with priority access</div>
          <div class="features">Deep intake, weekly touchpoints, customized toolkit</div>
          <a class="cta" href="{{PRIMARY_CTA_URL}}">Start Foundations</a>
        </article>
      </section>

      <section style="padding:0 28px 28px">
        <div style="display:flex;gap:18px;flex-wrap:wrap">
          <div style="flex:1;min-width:240px;background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.5)">
            <h4 style="margin:0 0 6px 0">Save with packages</h4>
            <p style="margin:0;color:var(--muted)">Three-month bundles reflect focused change cycles — clear checkpoints and measurable adjustments.</p>
          </div>
          <div style="flex:2;min-width:240px;background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.5)">
            <h4 style="margin:0 0 6px 0">Questions about fit?</h4>
            <p style="margin:0;color:var(--muted)">Call us at {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> for a short fit conversation before committing.</p>
          </div>
        </div>
      </section>

    </main>

    <footer>
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap">
        <div>{{BUSINESS_NAME}} &mdash; Membership offerings. No medical guarantees. Educational and supportive services only.</div>
        <div style="color:var(--muted)">© <span id="year"></span></div>
      </div>
    </footer>
  </div>

  <script>
    // year
    document.getElementById('year').textContent = new Date().getFullYear();

    // pricing toggle with animated numbers
    const btnMonthly = document.getElementById('btn-monthly');
    const btnPackage = document.getElementById('btn-package');
    const cards = document.querySelectorAll('.card');

    function animateValue(el, start, end, duration){
      const startTime = performance.now();
      function tick(now){
        const dt = Math.min(1, (now - startTime) / duration);
        const val = Math.round(start + (end - start) * dt);
        el.textContent = val;
        if(dt < 1) requestAnimationFrame(tick);
      }
      requestAnimationFrame(tick);
    }

    function setMode(mode){
      const isMonthly = mode === 'monthly';
      btnMonthly.classList.toggle('active', isMonthly);
      btnPackage.classList.toggle('active', !isMonthly);
      btnMonthly.setAttribute('aria-pressed', isMonthly);
      btnPackage.setAttribute('aria-pressed', !isMonthly);

      cards.forEach(card =>{
        const numEl = card.querySelector('.num');
        const from = parseInt(numEl.textContent,10) || 0;
        const to = parseInt(card.getAttribute(isMonthly ? 'data-monthly' : 'data-package'),10);
        const suffix = isMonthly ? ' /mo' : ' per 3 mo';
        animateValue(numEl, from, to, 600);
        // update trailing text
        const small = card.querySelector('.price span[style]');
        if(small){
          small.textContent = isMonthly ? ' /mo' : ' per 3 mo';
        }
      });
    }

    btnMonthly.addEventListener('click',()=>setMode('monthly'));
    btnPackage.addEventListener('click',()=>setMode('package'));

    // initial mode
    setMode('monthly');
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--glass:#ffffff19;--accent:#3b7d6f;--muted:#6f7f84;--bg:#f6f9f8;--card:#ffffffef}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#102022;background:linear-gradient(180deg,var(--bg),#eef4f2);}
    .wrap{min-height:100vh;display:flex;flex-direction:column;background-image:url('assets/img/pattern.svg');background-repeat:repeat}
    header{padding:18px 26px;display:flex;justify-content:space-between;align-items:center}
    .brand{display:flex;align-items:center;gap:12px}
    nav a{margin:0 10px;color:#173; text-decoration:none;font-weight:600}
    main{padding:28px}
    .card{background:var(--card);border-radius:14px;padding:20px;box-shadow:0 8px 28px rgba(12,18,16,0.06);border:1px solid rgba(255,255,255,0.5)}
    h1{margin:0 0 8px 0}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px;margin-top:18px}
    .mood{display:flex;flex-direction:column;gap:12px;background:linear-gradient(180deg,var(--glass),transparent);padding:14px;border-radius:12px}
    .mood button{padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.04);background:white;cursor:pointer}
    .mood button.active{background:linear-gradient(90deg,var(--accent),#5fa68f);color:white}
    .method{padding:14px;border-radius:12px;background:#fff;margin-top:12px}
    .cta{display:inline-block;padding:10px 12px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;font-weight:700;margin-top:12px}
    @media(max-width:980px){.grid{grid-template-columns:1fr}.mood{flex-direction:row;flex-wrap:wrap}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="brand">
        <div style="width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#6eb79a);display:grid;place-items:center;color:white;font-weight:800">HM</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">Holistic membership and guided programs</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="services.html">Offerings</a>
        <a href="conditions.html">Ailments</a>
        <a href="approach.html">Method</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">Who We Are</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Reach Out</a>
      </nav>
    </header>

    <main>
      <div class="card">
        <h1>Practice-based whole-person care</h1>
        <p style="color:var(--muted);margin-top:6px">We combine lifestyle guidance, thoughtful testing, and structured coaching to support gradual, durable changes. Services are educational and supportive; they are not promises of cure.</p>

        <div class="grid">
          <div>
            <h3 style="margin-top:14px">Our framing</h3>
            <p style="color:var(--muted)">We map an individualized pathway—some clients use on-demand membership to steady habits; others engage packages to navigate a focused cycle of change. Your plan may involve movement, nutritional patterns, sleep architecture, stress calibration, and selective labs when helpful.</p>

            <div style="margin-top:16px;display:flex;gap:12px;flex-wrap:wrap">
              <div style="background:var(--card);padding:12px;border-radius:10px;min-width:160px">Clinical Intake + Plan</div>
              <div style="background:var(--card);padding:12px;border-radius:10px;min-width:160px">Guided Practice Sessions</div>
              <div style="background:var(--card);padding:12px;border-radius:10px;min-width:160px">Community Calibration</div>
            </div>

            <h4 style="margin-top:18px">A note on safety</h4>
            <p style="color:var(--muted)">Our guidance complements existing medical care. If you have urgent symptoms, please seek immediate medical attention. We offer supportive, not definitive, services.</p>
          </div>

          <aside>
            <div class="mood" role="radiogroup" aria-label="Mood to Method selector">
              <strong>How are you feeling today?</strong>
              <button data-key="overwhelmed" class="active">Overwhelmed</button>
              <button data-key="low_energy">Low energy</button>
              <button data-key="tension">Tense / Wired</button>
              <button data-key="curious">Curious / Exploring</button>

              <div class="method card" id="method-card">
                <h4 id="method-title">Grounding Course</h4>
                <p id="method-desc" style="color:var(--muted)">Short weekly practices, prioritized sleep and regulation tools, and two focused consultations to stabilize habits and decision-making.</p>
                <a id="method-cta" class="cta" href="{{PRIMARY_CTA_URL}}">Start a stabilization visit</a>
              </div>
            </div>
          </aside>
        </div>

      </div>

      <section style="margin-top:18px">
        <div class="card">
          <h3>Team and philosophy</h3>
          <p style="color:var(--muted)">A small team of clinicians with cross-disciplinary backgrounds coordinate clear next steps and measurable checkpoints. We steward information: listen, experiment, and adjust. Memberships emphasize accountability and gradual skill-building.</p>
          <p style="margin-top:12px;color:var(--muted)">For bookings, use the Reserve page to choose an intake type that matches your immediate priorities.</p>
        </div>
      </section>

    </main>

    <footer style="padding:18px 26px;color:var(--muted)">
      <div>{{BUSINESS_NAME}} — Supportive educational services. Not a replacement for urgent medical care.</div>
    </footer>
  </div>

  <script>
    // Mood-to-Method logic
    const map = {
      overwhelmed: {
        title: 'Grounding Course',
        desc: 'Progressive regulation skills, nightly habit scaffolding, and two short clinical check-ins to re-establish routine and choice clarity.',
        cta: 'Begin stability pathway'
      },
      low_energy: {
        title: 'Energy Reset',
        desc: 'Focused intake, targeted nutrition and sleep adjustments, and a short follow-up cadence to restore consistent energy across weeks.',
        cta: 'Request an Energy Reset'
      },
      tension: {
        title: 'Calm Architecture',
        desc: 'A plan emphasizing nervous-system tools, paced movement, and stress-signal mapping with practical micro-protocols.',
        cta: 'Schedule Calm Architecture'
      },
      curious: {
        title: 'Exploratory Path',
        desc: 'Flexible orientation sessions to clarify goals and try small experiments — ideal for early-stage exploration.',
        cta: 'Start an exploratory consult'
      }
    };

    const buttons = document.querySelectorAll('.mood button');
    const titleEl = document.getElementById('method-title');
    const descEl = document.getElementById('method-desc');
    const ctaEl = document.getElementById('method-cta');

    function selectMood(key, btn){
      buttons.forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      const m = map[key];
      // subtle morph
      titleEl.style.opacity = 0; descEl.style.opacity = 0; ctaEl.style.opacity = 0;
      setTimeout(()=>{
        titleEl.textContent = m.title;
        descEl.textContent = m.desc;
        ctaEl.textContent = m.cta;
        ctaEl.href = '{{PRIMARY_CTA_URL}}';
        titleEl.style.opacity = 1; descEl.style.opacity = 1; ctaEl.style.opacity = 1;
      },180);
    }

    buttons.forEach(b=>{
      b.addEventListener('click',()=>selectMood(b.getAttribute('data-key'), b));
    });

    // initial
    selectMood('overwhelmed', document.querySelector('.mood button[data-key="overwhelmed"]'));
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#2f7a68;--muted:#6b7b80;--card:#ffffffef}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:linear-gradient(180deg,#f6fbfa,#eef6f4);color:#072226}
    .wrap{min-height:100vh;display:flex;flex-direction:column;background-image:url('assets/img/pattern.svg');background-repeat:repeat}
    header{padding:18px 24px;display:flex;justify-content:space-between;align-items:center}
    nav a{margin:0 10px;color:#133; text-decoration:none;font-weight:600}
    main{padding:24px}
    .grid{display:grid;grid-template-columns:1fr 340px;gap:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.6);box-shadow:0 8px 20px rgba(8,12,12,0.05)}
    .selector{display:flex;gap:10px;flex-wrap:wrap}
    .selector button{padding:10px;border-radius:10px;border:1px solid rgba(0,0,0,0.04);background:white;cursor:pointer}
    .selector button.active{background:linear-gradient(90deg,var(--accent),#67a890);color:#fff}
    .summary{margin-top:14px}
    .booking-cta{display:inline-block;padding:12px 16px;border-radius:12px;background:var(--accent);color:#fff;text-decoration:none;font-weight:700}
    @media(max-width:980px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="display:flex;align-items:center;gap:12px">
        <div style="width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#61a289);display:grid;place-items:center;color:white;font-weight:800">HM</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">Reserve a time that reflects what matters most now</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="services.html">Offerings</a>
        <a href="conditions.html">Ailments</a>
        <a href="approach.html">Method</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">Who We Are</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Reach Out</a>
      </nav>
    </header>

    <main>
      <div class="grid">
        <div>
          <div class="card">
            <h2>Reserve a session</h2>
            <p style="color:var(--muted)">Pick what fits your immediate priorities. The selector helps match an appointment style and updates the action below.</p>

            <div style="margin-top:14px">
              <strong>Choose your current state</strong>
              <div class="selector" role="radiogroup" aria-label="Mood to Method booking">
                <button data-key="overwhelmed" class="active">Overwhelmed</button>
                <button data-key="low_energy">Low energy</button>
                <button data-key="tension">Tense / Wired</button>
                <button data-key="curious">Exploring options</button>
              </div>

              <div class="summary card" id="booking-summary">
                <h4 id="b-title">Stabilization Intake</h4>
                <p id="b-desc" style="color:var(--muted)">45-minute intake focused on regulation, routine, and immediate practical steps.</p>
                <div style="margin-top:10px">Suggested length: <strong id="b-length">45 min</strong></div>
                <a id="b-cta" class="booking-cta" href="{{PRIMARY_CTA_URL}}">Reserve 45-min intake</a>
              </div>

            </div>
          </div>

          <div style="height:18px"></div>

          <div class="card">
            <h3 style="margin-top:0">What to expect</h3>
            <ul style="color:var(--muted)">
              <li>Concise intake to map priorities and safe first steps.</li>
              <li>Personalized short-term practices and clear follow-up cadence.</li>
              <li>Membership or packages recommended only when helpful.</li>
            </ul>
          </div>
        </div>

        <aside>
          <div class="card">
            <h4>Quick logistics</h4>
            <p style="color:var(--muted)">We offer virtual and limited in-person times. Please have a brief list of current medications and recent labs (if any) for the intake.</p>
            <div style="margin-top:10px">Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
          </div>

          <div style="height:12px"></div>

          <div class="card">
            <h4>Accessibility</h4>
            <p style="color:var(--muted)">If you need specific accommodations, note them when you reserve and we will confirm prior to the session.</p>
          </div>
        </aside>
      </div>
    </main>

    <footer style="padding:18px 24px;color:var(--muted)">Reservations coordinated by the team — supportive educational services only. If this is an emergency, seek urgent care.</footer>
  </div>

  <script>
    // Booking mood selector
    const bookingMap = {
      overwhelmed: {title: 'Stabilization Intake', desc: '45-minute intake focused on regulation and immediate steps.', length: '45 min', cta: 'Reserve 45-min intake', lengthMinutes:45},
      low_energy: {title: 'Energy Brief', desc: '30-minute focused visit to troubleshoot sleep, nutrition, and activity.', length: '30 min', cta: 'Reserve 30-min energy brief', lengthMinutes:30},
      tension: {title: 'Nervous-System Visit', desc: '50-minute session to map tension triggers and regulation practices.', length: '50 min', cta: 'Reserve 50-min session', lengthMinutes:50},
      curious: {title: 'Exploratory Chat', desc: '25-minute orientation to explore options and next steps.', length: '25 min', cta: 'Reserve exploratory chat', lengthMinutes:25}
    };

    const selButtons = document.querySelectorAll('.selector button');
    const bTitle = document.getElementById('b-title');
    const bDesc = document.getElementById('b-desc');
    const bLength = document.getElementById('b-length');
    const bCta = document.getElementById('b-cta');

    function applyBooking(key, btn){
      selButtons.forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      const val = bookingMap[key];
      // animate a small pulse
      bTitle.style.transform = 'translateY(6px)'; bTitle.style.opacity = 0; bDesc.style.opacity = 0; bCta.style.transform='scale(0.98)';
      setTimeout(()=>{
        bTitle.textContent = val.title;
        bDesc.textContent = val.desc;
        bLength.textContent = val.length;
        bCta.textContent = val.cta;
        // craft a URL fragment to hint at context (no external service)
        bCta.href = '{{PRIMARY_CTA_URL}}#type=' + encodeURIComponent(val.title) + '&len=' + val.lengthMinutes;
        bTitle.style.transform='translateY(0)'; bTitle.style.opacity = 1; bDesc.style.opacity = 1; bCta.style.transform='scale(1)';
      },180);
    }

    selButtons.forEach(b=>{
      b.addEventListener('click',()=>applyBooking(b.getAttribute('data-key'), b));
    });

    // init with 'overwhelmed'
    applyBooking('overwhelmed', document.querySelector('.selector button[data-key="overwhelmed"]'));
  </script>
